HANDLERS = {"received": _received, "reserved": _reserved, "written_off": _written_off, "fulfilled": _fulfilled}


def apply(state, event):
    handler = HANDLERS.get(event.get("type"))
    if handler is None:
        raise ValueError(f"unknown event type: {event!r}")
    handler(state, event)


def replay(events):
    """The State that applying `events` in order produces; their `n` must run 1, 2, 3, ..."""
    state = State()
    for expected, event in enumerate(events, start=1):
        if event.get("n") != expected:
            raise ValueError(f"event {expected} is out of sequence: {event!r}")
        apply(state, event)
    return state

