        buffer = OrderedBuffer()
        self.assertEqual(seqs(buffer.push([ev("a", B)])), [B])
        self.assertEqual(seqs(buffer.push([ev("a", B + 2)])), [])
        self.assertEqual(seqs(buffer.push([ev("a", B + 1)])), [B + 1, B + 2])

