        buffer = OrderedBuffer()
        buffer.push([ev("a", B), ev("a", B + 1)])
        again = OrderedBuffer.restore(json.loads(json.dumps(buffer.snapshot())))
        self.assertEqual(seqs(again.push([ev("a", B + 2)])), [B + 2])


