            raise ValueError(f"a job needs a unique non-empty name: {name!r}")
        deps = job.get("deps", [])
        if not isinstance(deps, (list, tuple)) or not all(isinstance(dep, str) for dep in deps):
            raise ValueError(f"deps of {name!r} must be a list of names")
