def run(jobs, execute, max_parallel=None, dry_run=False):
    table = check(jobs)
    waves = waves_for(table, max_parallel)
    if dry_run:
        return {"order": [name for wave in waves for name in wave], "failed": [], "skipped": {}, "attempts": {}}
    result = {"order": [], "failed": [], "skipped": {}, "attempts": {}}
    for wave in waves:
