"""Prorating by days (docs/rules.md)."""
import calendar
from datetime import date, timedelta

from .alloc import allocate
from .currency import round_div

INCLUSIVE = True


def _check_dates(*values):
    for value in values:
        if type(value) is not date:
            raise TypeError(f"expected a datetime.date, got {value!r}")


def count_days(start, end):
    """Days in the range under the convention, however far apart; ValueError when start is after end."""
    _check_dates(start, end)
    if start > end:
        raise ValueError(f"{start} is after {end}")
    return (end - start).days + (1 if INCLUSIVE else 0)


def month_period(year, month):
    """(start, end) of the calendar month under the convention."""
    first = date(year, month, 1)
    last_day = calendar.monthrange(year, month)[1]
    return first, first + timedelta(days=last_day - 1 if INCLUSIVE else last_day)


def _checked_period(period):
    start, end = period
    if count_days(start, end) < 1:
        raise ValueError("a period has at least one day")
    return start, end


def _used_days(period, start, end):
    """Days of (start, end) inside `period`; ValueError when start is after end."""
    count_days(start, end)
    period_start, period_end = period
    clipped_start, clipped_end = max(start, period_start), min(end, period_end)
    if clipped_start > clipped_end:
        return 0
    return count_days(clipped_start, clipped_end)


def prorate(amount, period, start, end):
    """The share of `amount` for the days of (start, end) that fall inside `period`."""
    period_start, period_end = _checked_period(period)
    used = _used_days(period, start, end)
    assert 0 <= used <= count_days(period_start, period_end), "used days stay inside the period"
    return round_div(amount * used, count_days(period_start, period_end))


def split_refund(amount_paid, period, cancel_on):
    """(charged, refund) for service up to `cancel_on`; the two add up to `amount_paid`."""
    period_start, _ = _checked_period(period)
    if cancel_on < period_start:
        raise ValueError("cancelled before the period began")
    charged = prorate(amount_paid, period, period_start, cancel_on)
    return charged, amount_paid - charged



def split_by_usage(amount, period, spans):
    """`amount` allocated over the spans by their used days inside `period`."""
    _checked_period(period)
    return allocate(amount, [_used_days(period, start, end) for start, end in spans])

solution.meadow_stream/buffer.py:
"""Per-source in-order delivery of an event stream (rules: docs/ordering.md)."""
import copy

FIRST = 0
WINDOW = 5


class GapError(ValueError):
    """A source's window was exceeded: `source` and the `missing` seqs, ascending."""

    def __init__(self, source, missing):
        super().__init__(f"{source}: seqs {missing} are missing and the window of {WINDOW} is exceeded")
        self.source, self.missing = source, missing



def _checked(event):
    """(source, seq) of a well-formed event; anything else is a ValueError."""
    if not isinstance(event, dict) or {"source", "seq", "payload"} - event.keys():
        raise ValueError(f"an event needs source, seq and payload: {event!r}")
    source, seq = event["source"], event["seq"]
    if not isinstance(source, str) or type(seq) is not int:
        raise ValueError(f"source must be a string and seq an int: {event!r}")
    if FIRST is not None and seq < FIRST:
        raise ValueError(f"seq {seq} is below the first seq {FIRST}")
    return source, seq


class OrderedBuffer:
    def __init__(self):
        self._next = {}
        self._held = {}
        self.missing = []

    def push(self, events):
        """Accept events in the given order; return the events that became deliverable, in delivery order."""
        next_seq, held, missing = self._copy_state()
        delivered = []
        for event in events:
            self._accept(event, next_seq, held, missing, delivered)
        self._next, self._held, self.missing = next_seq, held, missing
        return delivered

    def _copy_state(self):
        return dict(self._next), {s: dict(h) for s, h in self._held.items()}, list(self.missing)

    @staticmethod
    def _accept(event, next_seq, held, missing, delivered):
        source, seq = _checked(event)
        if source not in next_seq:
            next_seq[source] = seq if FIRST is None else FIRST
            held[source] = {}
        expected, pending = next_seq[source], held[source]
        if seq < expected or seq in pending:
            return
        if seq - expected >= WINDOW:
            raise GapError(source, [n for n in range(expected, seq) if n not in pending])
        pending[seq] = event
        while expected in pending:
            delivered.append(pending.pop(expected))
            expected += 1
        next_seq[source] = expected

    def snapshot(self):
        """JSON-compatible state that `restore` turns back into an equivalent buffer."""
        return {"next": dict(self._next),
                "held": {s: [copy.deepcopy(h[n]) for n in sorted(h)] for s, h in self._held.items()},
                "missing": [list(item) for item in self.missing]}

    @classmethod
    def restore(cls, snapshot):
        buffer = cls()
        buffer._next = dict(snapshot["next"])
        buffer._held = {s: {e["seq"]: copy.deepcopy(e) for e in events} for s, events in snapshot["held"].items()}
        buffer.missing = [list(item) for item in snapshot["missing"]]
        assert set(buffer._next) == set(buffer._held), "a snapshot holds the same sources in next and held"
        return buffer

