import calendar
from datetime import date, timedelta

from .alloc import allocate
from .currency import round_div

INCLUSIVE = True


def _check_dates(*values):
    for value in values:
        if type(value) is not date:
            raise TypeError(f"expected a datetime.date, got {value!r}")


