import json
import re
from datetime import datetime, timedelta, timezone
from decimal import ROUND_DOWN, ROUND_HALF_EVEN, ROUND_HALF_UP, Decimal

V1_FIELDS = ("id", "title", "owner", "price", "updated")
ROUNDING = ROUND_DOWN
PRICE = re.compile(r"-?\d+(\.\d+)?")
ISO = "%Y-%m-%dT%H:%M:%SZ"
OFFSET_HOURS = 0


def schema_of(text):
    """1 or 2: a first non-blank line that is exactly `{"schema": 2}` marks v2."""
    for line in text.split("\n"):
        if not line.strip():
            continue
        try:
            first = json.loads(line)
        except ValueError:
            return 1
        if not (isinstance(first, dict) and set(first) == {"schema"}):
            return 1
        if first["schema"] != 2 or type(first["schema"]) is not int:
            raise ValueError(f"unsupported schema {first['schema']!r}")
        return 2
    return 1


def parse_v2(text):
    """The records of a v2 file, without the header line."""
    lines = [line for line in text.split("\n") if line.strip()]
    assert not lines or json.loads(lines[0]) == {"schema": 2}, "a v2 file starts with its header"
    return [json.loads(line) for line in lines[1:]]


def render_records(records):
    """Canonical v2 text: the header, then one compact sorted-key line per record."""
    lines = ['{"schema":2}']
    lines += [json.dumps(record, sort_keys=True, separators=(",", ":"), ensure_ascii=False) for record in records]
    return "\n".join(lines) + "\n"

def price_to_minor(value):
    """Minor units of a v1 price string, rounded as docs/schema.md says; None stays None."""
    if value is None:
        return None
    if not isinstance(value, str) or not PRICE.fullmatch(value.strip()):
        raise ValueError(f"price must be a decimal string: {value!r}")
    return int((Decimal(value.strip()) * 100).quantize(Decimal(1), rounding=ROUNDING))

def split_owner(owner):
    """(first, last) of a "First Middle Last" owner; None stays None."""
    if owner is None:
        return None, None
    if not isinstance(owner, str):
        raise ValueError(f"owner must be text: {owner!r}")
    words = owner.split()
    return " ".join(words[:-1]), (words[-1] if words else "")

def to_utc_iso(value):
    """ISO UTC text of a v1 epoch-seconds int; None stays None."""
    if value is None:
        return None
    if type(value) is not int:
        raise ValueError(f"updated must be integer seconds: {value!r}")
    return datetime.fromtimestamp(value, timezone.utc).strftime(ISO)

def upgrade_record(old):
    """The v2 record for one v1 record; ValueError when the record is bad."""
    if not isinstance(old, dict) or not isinstance(old.get("id"), str) or not old["id"]:
        raise ValueError(f"a record needs a non-empty string id: {old!r}")
    first, last = split_owner(old.get("owner"))
    record = {"id": old["id"], "name": old.get("title"), "owner_first": first, "owner_last": last,
              "price_minor": price_to_minor(old.get("price")), "updated_at": to_utc_iso(old.get("updated"))}
    extra = {key: value for key, value in old.items() if key not in V1_FIELDS}
    if extra:
        record["extra"] = extra
    return record

