def _start(rows, scope, cursor):
    """Index in `rows` of the first row after the cursor's position."""
    if cursor is None:
        return 0
    return _open(scope, cursor)["offset"]


def _token(scope, page, start):
    return encode({**scope, "offset": start + len(page)})


